-- Portable validator for the finite JSON Schema subset generated by our Zod aggregate.
-- Not a general-purpose JSON Schema implementation: supported keywords are explicitly tested.
create function public.matches_project_shape(candidate_value jsonb,shape jsonb) returns boolean language plpgsql immutable set search_path='' as $$
declare kind text;item jsonb;prop record;key text;begin
 if candidate_value is null then return false;end if;
 kind=shape->>'type';
 if kind='integer' then
 if jsonb_typeof(candidate_value)<>'number' then return false;end if;
 if (candidate_value#>>'{}')::numeric<>trunc((candidate_value#>>'{}')::numeric) then return false;end if;
 elsif kind is not null and jsonb_typeof(candidate_value)<>kind then return false;end if;
 if shape ? 'enum' and not exists(select 1 from jsonb_array_elements(shape->'enum') e where e=candidate_value) then return false;end if;
 if kind='object' then
 for item in select * from jsonb_array_elements(coalesce(shape->'required','[]')) loop if not(candidate_value ? (item#>>'{}')) then return false;end if;end loop;
 for prop in select * from jsonb_each(candidate_value) loop
 if not(coalesce(shape->'properties','{}') ? prop.key) then if shape->'additionalProperties'='false' then return false;end if;
 elsif not public.matches_project_shape(prop.value,shape->'properties'->prop.key) then return false;end if;
 end loop;
 elsif kind='array' then
 if shape ? 'maxItems' and jsonb_array_length(candidate_value)>(shape->>'maxItems')::integer then return false;end if;
 for item in select * from jsonb_array_elements(candidate_value) loop if not public.matches_project_shape(item,shape->'items') then return false;end if;end loop;
 elsif kind='string' then
 key=candidate_value#>>'{}';
 if shape ? 'minLength' and length(key)<(shape->>'minLength')::integer then return false;end if;
 if shape ? 'maxLength' and length(key)>(shape->>'maxLength')::integer then return false;end if;
 if shape ? 'pattern' and key !~ (shape->>'pattern') then return false;end if;
 elsif kind in ('number','integer') then
 if shape ? 'minimum' and (candidate_value#>>'{}')::numeric<(shape->>'minimum')::numeric then return false;end if;
 if shape ? 'maximum' and (candidate_value#>>'{}')::numeric>(shape->>'maximum')::numeric then return false;end if;
 if shape ? 'exclusiveMinimum' and (candidate_value#>>'{}')::numeric<=(shape->>'exclusiveMinimum')::numeric then return false;end if;
 end if;return true;
end$$;
revoke all on function public.matches_project_shape(jsonb,jsonb) from public;
grant execute on function public.matches_project_shape(jsonb,jsonb) to authenticated;

